"""Scalar synthetic volume publication probe, not a biological analysis.

Register this complete source through ordinary MCP only after the blind runtime
slot closes. Plane indices select an explicit ordered subset of the input Z
stack; the compiled pipeline, not this callable, must establish the Z axis.
"""

from dataclasses import dataclass

from arraybridge import ArrayPayload
import numpy as np

from openhcs.core.artifacts import (
    ImageArtifactType,
    MainFlowStackOutputSpec,
    MeasurementsArtifactType,
    ObjectLabelsArtifactType,
    ObjectMeasurementSubjectRelation,
)
from openhcs.core.measurement_row_materialization import DataclassMeasurementColumnarRows
from openhcs.core.memory import numpy
from openhcs.core.pipeline.function_contracts import artifact_outputs
from openhcs.core.runtime_image_values import image_payload_data, image_payload_metadata
from openhcs.core.runtime_measurements import RuntimeMeasurementFeature, RuntimeMeasurementFeatureOwner
from openhcs.processing.backends.lib_registry.unified_registry import ProcessingContract
from openhcs.processing.materialization import CsvOptions, MaterializationSpec, ROIOptions


class VolumeFixtureFeature(RuntimeMeasurementFeature):
    PIXEL_COUNT = "pixel_count"


class VolumeFixtureFeatureOwner(RuntimeMeasurementFeatureOwner):
    @classmethod
    def owns_measurement_feature_name(cls, feature_name: str) -> bool:
        return any(feature.feature_name == feature_name for feature in VolumeFixtureFeature)

    @classmethod
    def owns_primary_measurement_feature_name(cls, feature_name: str) -> bool:
        return cls.owns_measurement_feature_name(feature_name)


@dataclass(frozen=True)
class VolumeFixtureRow:
    slice_index: int
    object_label: int
    pixel_count: int


VOLUME_IMAGE = MainFlowStackOutputSpec.output("volume_fixture_image", ImageArtifactType)
VOLUME_LABELS = MainFlowStackOutputSpec.output(
    "volume_fixture_labels",
    ObjectLabelsArtifactType,
    materialization=MaterializationSpec(ROIOptions(min_area=0)),
)
VOLUME_ROWS = MainFlowStackOutputSpec.output(
    "volume_fixture_rows",
    MeasurementsArtifactType,
    measurement_feature_owner=VolumeFixtureFeatureOwner,
    relations=(ObjectMeasurementSubjectRelation(source=VOLUME_LABELS.ref(), id_field="object_label"),),
    materialization=MaterializationSpec(CsvOptions()),
)


@numpy(contract=ProcessingContract.PURE_3D)
@artifact_outputs(VOLUME_IMAGE, VOLUME_LABELS, VOLUME_ROWS)
def inspect_volume_fixture(
    image: ArrayPayload,
    plane_indices: tuple[int, ...] = (),
) -> tuple[ArrayPayload, ArrayPayload, DataclassMeasurementColumnarRows]:
    """Return exact selected pixels, instance IDs and per-plane synthetic rows."""
    pixels = image_payload_data(image)
    if pixels.ndim != 3 or not np.issubdtype(pixels.dtype, np.integer):
        raise ValueError("Expected an integer scalar ZYX fixture")
    if np.any(pixels < 0):
        raise ValueError("Fixture object IDs must be non-negative")
    indices = plane_indices or tuple(range(pixels.shape[0]))
    if len(set(indices)) != len(indices):
        raise ValueError("Fixture selections must not repeat a source plane")
    # The existing metadata owner checks source-plane bounds and projects the
    # exact same ordered indices as the pixels. No filename/address synthesis.
    metadata = image_payload_metadata(image).for_source_planes(indices)
    selected = np.take(pixels, indices, axis=0)
    labels = selected.astype(np.int32, copy=True)
    rows = tuple(
        VolumeFixtureRow(index, int(label), int(np.count_nonzero(plane == label)))
        for index, plane in enumerate(labels)
        for label in np.unique(plane)
        if label != 0
    )
    return (
        metadata.payload_with(selected.copy()),
        metadata.payload_with(labels),
        DataclassMeasurementColumnarRows(rows, row_type=VolumeFixtureRow),
    )

